    return objs
def norm(cells):
    pts=list(cells); r0=min(p[0] for p in pts); c0=min(p[1] for p in pts)
    return frozenset((p[0]-r0,p[1]-c0) for p in pts)
def solve(I,O=None):
    h,w=I.shape
    bg=Counter(x for x in I.flatten().tolist()).most_common(1)[0][0]
    objs=comps(I,bg)
    cc=Counter(o['col'] for o in objs)
    # target color: color with exactly one component, largest
    singles=[o for o in objs if cc[o['col']]==1]
    if singles:
        tcol=max(singles,key=lambda o:len(o['cells']))['col']
        tmpl=[o for o in objs if o['col']==tcol][0]['cells']
    else:
        # fallback: color with fewest total cells
        cnts={}
        for o in objs: cnts.setdefault(o['col'],0); cnts[o['col']]+=len(o['cells'])
        tcol=min(cnts,key=lambda c:cnts[c])
        tp=sorted({p for o in objs if o['col']==tcol for p in o['cells']})
        tmpl=set(tp)
    gr=defaultdict(list)
    for o in objs: gr[norm(o['cells'])].append(o)
    out=I.copy()
    best=None
    for sh,v in gr.items():
        if len(v)==2:
            for i,o in enumerate(v):
                pts=o['cells']
                md=min(abs(p[0]-q[0])+abs(p[1]-q[1]) for p in pts for q in tmpl)/len(pts)
                if best is None or md>best[0]:
                    best=(md,i,o)
    if best:
        md,i,o=best
        for p in o['cells']: out[p]=tcol
    return out
