def comps(I,bg):
    h,w=I.shape; lab=np.zeros_like(I,dtype=int); out=[]
    for r in range(h):
        for c in range(w):
            if I[r,c]!=bg and lab[r,c]==0:
                col=int(I[r,c]); st=[(r,c)]; cells=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in cells: continue
                    cells.add((a,b))
                    for da_,db_ in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da_,b+db_
                        if 0<=na<h and 0<=nb<w and I[na,nb]==col and lab[na,nb]==0:
                            st.append((na,nb)); lab[na,nb]=1
                out.append({'col':col,'cells':sorted(cells)})
    return out
